-- Russian quest titles and objective lines for 273 Forever quests that showed English on Russian clients, among them the
-- 8 Zephras quests a player reported (92834, 92860, 93089, 93459, 93835, 94369, 94946, 99260).
-- Text: Wowhead (Forever, Russian quest tooltips), with thanks to Wowhead. A tooltip holds only the title and the objective
-- line, so the long story text of these quests stays English.
-- Only fills a missing or empty Russian field; an existing one is kept. Safe to run again.
SET NAMES utf8mb4;

ON DUPLICATE KEY UPDATE `LogTitle` = IF(`LogTitle` IS NULL OR `LogTitle` = '', VALUES(`LogTitle`), `LogTitle`), `LogDescription` = IF(`LogDescription` IS NULL OR `LogDescription` = '', VALUES(`LogDescription`), `LogDescription`);
